'use strict';
const M=StillModel,P=M.products,$=s=>document.querySelector(s),main=$('#main'),sheet=$('#sheet'),body=$('#sheet-body'),native=!!window.StillAndroid;
let state,storageError='',page='now',selectedDay=M.day(),month=new Date(new Date().getFullYear(),new Date().getMonth(),1),photoPending=null,stream=null,photoCallback=null,renderTick,toastTick,savingRemoval=false,timelineDays=7;
const crampLabels=["Barely there","Mild","Moderate","Strong","Severe","Very severe"];
const safe=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
try{const raw=native?StillAndroid.getState():localStorage.getItem('still-in-v1');state=raw?M.validate(JSON.parse(raw)):M.blank()}catch(e){state=M.blank();storageError='Saved data could not be read. Reload the app before making changes.'}
const time=ts=>new Date(ts).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'}),dateLabel=d=>new Date(d+'T12:00:00').toLocaleDateString([],{weekday:'long',day:'numeric',month:'long'}),durationText=ms=>{const m=Math.floor(ms/60000);return `${Math.floor(m/60)}h ${m%60}m`},id=()=>crypto.randomUUID();
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTick);toastTick=setTimeout(()=>$('#toast').classList.remove('show'),3600)}
function save(){if(storageError)throw Error(storageError);const raw=JSON.stringify(state);if(native){const r=StillAndroid.saveState(raw);if(r!=='ok')throw Error(r||'Could not save. Try again.')}else localStorage.setItem('still-in-v1',raw)}
function transaction(fn){const before=JSON.stringify(state);try{const result=fn();save();return result}catch(e){state=JSON.parse(before);throw e}}
function doAction(fn){try{fn()}catch(e){toast(e.message)}}
const eye='<circle cx="39" cy="43" r="2.4" fill="#36151f"/><circle cx="57" cy="43" r="2.4" fill="#36151f"/><path d="M43 51q5 5 10 0" fill="none" stroke="#36151f" stroke-width="2.3" stroke-linecap="round"/><ellipse cx="32" cy="49" rx="4" ry="2" fill="#ee9db4"/><ellipse cx="64" cy="49" rx="4" ry="2" fill="#ee9db4"/>';
function legacyArt(type,soak=0,sleep=false){const fill=['#fff9f7','#f5ceda','#ed9db8','#d9638b','#b93662'][soak],stroke='#78253b';let shape='';if(type==='tampon')shape=`<path d="M36 65V24a12 12 0 0124 0v41q0 8-12 8T36 65" fill="${fill}" stroke="${stroke}" stroke-width="2.8"/><path d="M43 21v11m10-11v11M48 73q15 8 3 15" fill="none" stroke="${stroke}" stroke-width="2.8" stroke-linecap="round"/>`;
else if(type==='cup')shape=`<path d="M20 23h56l-7 34q-4 16-21 16T27 57z" fill="#d85c74" stroke="${stroke}" stroke-width="2.8"/><path d="M29 56q19-8 38 0l-2 7q-17 19-34 0z" fill="#b93655"/><rect x="18" y="18" width="60" height="9" rx="4.5" fill="#ffacb9" stroke="${stroke}" stroke-width="2.8"/><path d="M48 74v10" stroke="${stroke}" stroke-width="5" stroke-linecap="round"/>`;
else if(type==='disc')shape=`<ellipse cx="48" cy="46" rx="35" ry="21" fill="#bc727e" stroke="#7e3544" stroke-width="2.8"/><path d="M14 44q0 31 34 31t34-31" fill="#ad5468" stroke="#7e3544" stroke-width="2.8"/><ellipse cx="48" cy="41" rx="34" ry="18" fill="#f0b8c4" stroke="#7e3544" stroke-width="3"/><path d="M26 36q9-8 23-8" stroke="white" stroke-width="4" stroke-linecap="round" fill="none"/>`;
else if(type==='pad'||type==='liner')shape=`<path d="M33 22q-4-13 15-13t15 13l-3 15q17-2 17 9t-17 8l3 17q4 15-15 15T33 71l3-17q-17 3-17-8t17-9z" fill="#ae7b88" stroke="${stroke}" stroke-width="2.5"/><rect x="34" y="18" width="28" height="60" rx="14" fill="${fill}" stroke="${stroke}" stroke-width="1.6"/>`;
else if(type==='pants')shape=`<path d="M10 23h76l-6 29q-14 3-22 24H38q-8-21-22-24z" fill="#c85069" stroke="#7d293e" stroke-width="2.8"/><path d="M11 28h74M32 30q2 32 8 44m24-44q-2 32-8 44" fill="none" stroke="#f8b6c7" stroke-width="4"/>`;
return `<svg class="product-art" viewBox="0 0 96 96" aria-hidden="true">${shape}${sleep?'<path d="M36 44q4 4 8 0m9 0q4 4 8 0" stroke="#36151f" stroke-width="2.4" fill="none" stroke-linecap="round"/><text x="72" y="18" fill="#ff7688" font-size="16" font-weight="bold">z</text>':eye}</svg>`}
function drop(flow){const fills={none:'#4a3841',spotting:'#9b5366',light:'#c35875',medium:'#e04c71',heavy:'#f32f58'};return `<svg viewBox="0 0 30 36" aria-hidden="true"><path d="M15 2C13 9 3 16 3 23a12 12 0 0024 0C27 16 17 9 15 2Z" fill="${fills[flow]}"/><path d="M8 23q0 6 5 7" fill="none" stroke="#fff9" stroke-width="2.5" stroke-linecap="round"/>${flow==='none'?'<path d="M6 29L24 11" stroke="#baa1ad" stroke-width="2"/>':''}</svg>`}
const flows=['none','spotting','light','medium','heavy'];
function flowUI(day){const chosen=state.days[day]?.flow;return `<div class="flow-options">${flows.map(f=>`<button class="flow-option ${chosen===f?'selected':''}" data-flow="${f}" data-day="${day}" aria-pressed="${chosen===f}">${drop(f)}${f==='none'?'No blood':f[0].toUpperCase()+f.slice(1)}</button>`).join('')}</div>`}
function setupStatus(){if(!native)return null;try{return JSON.parse(StillAndroid.status())}catch(e){return {notifications:false,exact:false}}}
function warning(){if(!native)return `<div class="native-warning"><strong>Meet your new period sidekick.</strong><br>Try the draft here. Phone alarms work in the Android app.<br><a class="btn secondary" href="still-in-0.3.apk" download>↓ Get the Android app</a></div>`;const s=setupStatus();return !s.notifications||!s.exact?`<div class="native-warning"><strong>${!s.notifications?'Phone reminders are off':'Precise alarms need permission'}</strong><br>${!s.notifications?'Allow notifications to get removal reminders.':'Your reminders may arrive late until this is enabled.'}<br><button class="btn secondary" data-setup>Set up reminders</button></div>`:''}
function render(){clearInterval(renderTick);document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===page));if(page==='now')renderNow();if(page==='calendar')renderCalendar();if(page==='history')renderHistory();bind();if(page==='now')renderTick=setInterval(updateTimers,1000);updateTimers()}
function renderNow(){
 const today=M.day(),active=[...state.active].sort((a,b)=>a.due-b.due),night=state.days[today]?.nothingTonight;
 main.innerHTML=`${storageError?`<p class="error">${safe(storageError)}</p>`:''}<div class="now-heading"><div class="eyebrow">${new Date().toLocaleDateString([],{weekday:'long',day:'numeric',month:'short'})}</div><h1>${active.length?P[active[0].type].name+(P[active[0].type].internal?' is in.':' is on.'):'All quiet down here.'}</h1></div>${active.length?active.map((x,i)=>i===0?`<section class="velvet-hero" data-timer="${x.id}"><div class="velvet-stage"><div class="gothic-arch" aria-hidden="true"><svg viewBox="0 0 340 260"><path d="M18 258V142Q18 55 170 8Q322 55 322 142V258M26 258V142Q26 63 170 17Q314 63 314 142V258M7 143h30m266 0h30M158 10l12-9 12 9"/><path class="moon" d="M178 36a18 18 0 1018 27 21 21 0 01-18-27Z"/></svg></div><div class="stage-scene" data-stage-art data-frame="${M.dripFrame(x).key}">${stageArt(x)}</div></div>${wearTimeline(x)}<button class="btn velvet-button full" data-remove="${x.id}">${P[x.type].verb}</button><p class="illustration-note">Wear time, not measured fullness</p></section>`:`<section class="card secondary-wear" data-timer="${x.id}"><div class="row">${art(x.type)}<h3>${P[x.type].name}</h3><button class="btn secondary" data-remove="${x.id}">${P[x.type].verb}</button></div>${wearTimeline(x,true)}</section>`).join(''):`<section class="velvet-hero empty-velvet"><div class="velvet-stage"><div class="gothic-arch" aria-hidden="true"><svg viewBox="0 0 340 260"><path d="M18 258V142Q18 55 170 8Q322 55 322 142V258M26 258V142Q26 63 170 17Q314 63 314 142V258"/></svg></div>${DripArt.scene('everyday',night?3:1,'drip-art','Drip off duty')}</div><h2>${night?(state.settings.cheeky?'No backup. Brave.':'Off duty tonight.'):'Nothing in. Nothing on.'}</h2><p class="caption">${night?(state.settings.cheeky?'The sheets wish you luck.':'Logged for tonight.'):'Drip’s on a break. Pick your protection.'}</p></section>`}<div class="row section-title"><h2>Protection</h2><button class="plain-link" data-choose>All products</button></div><div class="product-grid velvet-products">${['tampon','cup','disc','pad'].map(k=>`<button class="product-btn ${active.some(x=>x.type===k)?'wearing':''}" data-add="${k}">${art(k)}<span>${P[k].name}</span></button>`).join('')}</div><section class="report-banner"><div><h2>Plot twist?</h2><span class="caption">Cramps, leaks, morning surprises…</span></div><button class="btn secondary" data-report>＋ Report</button></section><section class="card flow-card"><div class="row"><h2>Today's flow</h2><button class="plain-link" data-calendar>Calendar</button></div>${flowUI(today)}</section>${!active.length&&!night?`<button class="btn outline full" data-nothing>☾ Nothing tonight</button>`:''}${warning()}`;
}
function updateTimers(){for(const x of state.active){const el=document.querySelector(`[data-timer="${x.id}"]`);if(!el)continue;const t=M.timer(x),pct=Math.round(t.progress*100),track=el.querySelector('.wear-track');el.classList.toggle('overdue',t.overdue);if(track){track.setAttribute('aria-valuenow',String(pct));track.querySelector('.wear-fill').style.width=pct+'%';track.querySelector('.wear-now').style.left=Math.max(2,Math.min(98,pct))+'%'}const status=el.querySelector('[data-timer-label]');if(status)status.textContent=t.overdue?'Overdue by '+durationText(t.ms)+' · '+P[x.type].verb.toLowerCase()+' now':durationText(Date.now()-x.start)+' elapsed · '+durationText(t.ms)+' left';const artwork=el.querySelector('[data-stage-art]'),frame=M.dripFrame(x);if(artwork&&artwork.dataset.frame!==frame.key){artwork.innerHTML=stageArt(x);artwork.dataset.frame=frame.key}}}
function renderCalendar(){if((state.settings.calendarView||'timeline')==='timeline'){renderCalendarTimeline();return}const y=month.getFullYear(),m=month.getMonth(),offset=(new Date(y,m,1).getDay()+6)%7,count=new Date(y,m+1,0).getDate(),today=M.day();main.innerHTML=calendarTop('month')+`<section class="card">${monthNavigation()}<div class="calendar-grid">${['M','T','W','T','F','S','S'].map(d=>`<div class="weekday">${d}</div>`).join('')}${'<div></div>'.repeat(offset)}${Array.from({length:count},(_,i)=>{const d=M.day(new Date(y,m,i+1)),status=dayStatus(d),flow=status.flow==='unlogged'?null:status.flow,logs=M.entriesForDay(state,d).length;return `<button class="day ${d===selectedDay?'selected':''} ${d===today?'today':''}" ${flow?`data-flow="${flow}"`:''} data-date="${d}" aria-label="${dateLabel(d)}, ${safe(status.label)}${logs?', '+logs+' events':''}">${i+1}<span class="mini">${logs?'•':''}</span></button>`}).join('')}</div><div class="legend">${flows.slice(1).map((f,i)=>`<span><i style="background:${['#332027','#612435','#99314a','#c72d4e'][i]}"></i>${f[0].toUpperCase()+f.slice(1)}</span>`).join('')}</div></section><section class="card flow-card"><div class="row"><h3>${dateLabel(selectedDay)}</h3>${state.days[selectedDay]?.flow?'<button class="plain-link" data-clear-flow>Clear flow</button>':''}</div>${selectedDay>today?'<p class="caption">Future date. Log your flow when the day arrives.</p>':flowUI(selectedDay)}<div class="field"><label for="day-note">Day note <span class="muted">Optional</span></label><textarea id="day-note" maxlength="1000" rows="2" placeholder="Anything to remember…">${safe(state.days[selectedDay]?.note||'')}</textarea></div><button class="btn secondary full" data-save-note>Save note</button></section>${dayEntries(selectedDay)}<div class="footer-note">Dots include reports and product changes.<br>Blank days mean unlogged, not blood-free.</div>`}
function historyRows(logs){return logs.map(x=>`<div class="history-row">${art(x.type,x.soak??0)}<div class="history-text"><strong>${P[x.type].name}</strong><div class="caption">${time(x.start)} – ${time(x.end)} · ${durationText(x.end-x.start)}</div><div class="caption">${x.soak===null||x.soak===undefined?'':['Dry','A little soaked','Half soaked','Mostly soaked','Fully soaked'][x.soak]}${x.leaked?' · Leaked':''}${x.reinserted?' · Emptied + back in':''}</div>${x.photo?`<button class="receipt-photo" data-view-photo="${safe(x.photo)}">▧ View private photo</button>`:''}</div><div class="amount">${x.ml!==null&&x.ml!==undefined?`${x.ml} ml`:''}</div><button class="icon-button" data-log="${x.id}" aria-label="View ${P[x.type].name} log">⋯</button></div>`).join('')}
function renderHistory(){const days=[...new Set([...state.history.map(x=>M.day(x.end)),...(state.events||[]).map(x=>M.day(x.at))])].sort().reverse(),collected=state.history.reduce((s,x)=>s+(x.ml??0),0);main.innerHTML=`<div class="eyebrow">The evidence</div><h1>The receipts.</h1><div class="stats"><div class="stat"><strong>${state.history.length}</strong><small>Product changes</small></div><div class="stat"><strong>${collected}<span style="font-size:16px"> ml</span></strong><small>Collected & logged</small></div></div>${days.length?days.map(d=>`<div class="history-date">${dateLabel(d)}</div>${dayEntries(d)}`).join(''):`<section class="empty-history">${DripArt.scene('everyday',2)}<h2>No receipts. Yet.</h2><p class="caption">Your changes and reports will land here.</p></section>`}<div class="footer-note">Collected ml and saturation come from your entries.<br>Photos stay hidden until you tap to view.</div>`}
function show(content){body.innerHTML=content;if(!sheet.open)sheet.showModal();bindSheet()}
function head(title){return `<div class="sheet-head"><h2>${title}</h2><button class="icon-button" data-close aria-label="Close">×</button></div>`}
function closeSheet(){if(savingRemoval)return;if(stream){stream.getTracks().forEach(t=>t.stop());stream=null}sheet.close();photoCallback=null}
function choose(){show(head('What are you using?')+`<div class="product-grid">${Object.keys(P).map(k=>`<button class="product-btn" data-add="${k}">${art(k)}${P[k].name}</button>`).join('')}</div>`)}
function openAdd(type){if(state.active.some(x=>x.type===type)){toast('Already wearing one — log its removal first.');return}if(P[type].internal&&state.active.some(x=>P[x.type].internal)){toast('Take out your current internal product first.');return}let hours=state.settings.hours[type]||P[type].hours;show(head(P[type].internal?'Going in?':'Going on?')+`<form id="add-form"><div class="product-intro">${art(type)}<div><h3>${P[type].name}</h3><span class="caption">${P[type].internal?'A little occupied.':'Backup has arrived.'}</span></div></div><div class="field"><label for="start-time">${P[type].internal?'Put in':'Put on'}</label><input id="start-time" type="datetime-local" required value="${localInput(Date.now())}" max="${localInput(Date.now())}"></div><div class="field"><label>Remind me after</label><div class="chips">${[2,4,6,8,10,12].filter(h=>h<=P[type].max).map(h=>`<button type="button" class="chip ${h===hours?'selected':''}" data-hours="${h}">${h}h</button>`).join('')}</div><input type="hidden" id="wear-hours" value="${hours}"></div><p class="note">${type==='tampon'?'Change every 4–8 hours, sooner if needed. Never more than 8 hours.':'Follow your product’s wear-time instructions. Choose a shorter reminder if needed.'}${P[type].ml?' Emptying and reinserting starts a fresh timer.':''}</p><button class="btn full" type="submit">${P[type].internal?'It’s in. Start timer.':'It’s on. Start timer.'}</button><div id="form-error"></div></form>`);$('#add-form').onsubmit=e=>{e.preventDefault();try{const at=new Date($('#start-time').value).getTime(),h=Number($('#wear-hours').value);if(!Number.isFinite(at))throw Error('Choose a start time');transaction(()=>{M.add(state,type,h,at);const d=M.day();if(state.days[d])delete state.days[d].nothingTonight});closeSheet();page='now';render();toast(M.timer(state.active.find(x=>x.type===type)).overdue?'Logged — this product is already due for removal.':P[type].name+' timer started');insertedConfirmation(type)}catch(e){$('#form-error').innerHTML=`<p class="error">${safe(e.message)}</p>`}}}
function localInput(ts){const d=new Date(ts);return `${M.day(ts)}T${String(d.getHours()).padStart(2,'0')}:${String(d.getMinutes()).padStart(2,'0')}`}
function openRemove(sessionId){const x=state.active.find(x=>x.id===sessionId);if(!x)return;let soak=null;photoPending=null;show(head(P[x.type].internal?'Coming out.':'Time for a change.')+`<form id="remove-form"><div class="product-intro">${art(x.type)}<div><h3>${P[x.type].name}</h3><span class="caption">In use for ${durationText(Date.now()-x.start)}</span></div></div>${P[x.type].ml?'<div class="field"><label for="collected">How much collected? <span class="muted">Optional</span></label><div class="row"><input id="collected" type="number" min="0" max="500" step="0.1" inputmode="decimal" placeholder="e.g. 15"><strong>ml</strong></div></div>':`<div class="field"><label>How soaked? <span class="muted">Optional</span></label><div class="soak">${['Dry','A little','Half','Mostly','Full'].map((s,i)=>`<button type="button" data-soak="${i}">${art(x.type,i)}${s}</button>`).join('')}</div></div>`}<label class="switch-row"><span class="label">Leaked?</span><input type="checkbox" id="leaked"></label><button type="button" class="photo-button" id="take-photo">▧ Add a private photo</button><div id="photo-area"></div><p class="note">Taken in the app. Kept out of your phone’s gallery.</p><div id="form-error"></div><button class="btn full" type="submit" data-action="remove">${P[x.type].internal?'It’s out':'Changed'} · save</button>${P[x.type].ml?'<button class="btn secondary full spaced" type="submit" data-action="reinsert">Emptied + back in</button>':`<button class="btn secondary full spaced" type="submit" data-action="replace">Save + ${P[x.type].internal?'put a fresh one in':'use a fresh one'}</button>`}<button class="btn outline full spaced" type="submit" data-action="nothing">☾ ${state.settings.cheeky?'Nothing tonight. Living dangerously.':'Nothing tonight'}</button></form>`);
body.querySelectorAll('[data-soak]').forEach(b=>b.onclick=()=>{soak=Number(b.dataset.soak);body.querySelectorAll('[data-soak]').forEach(c=>c.classList.toggle('selected',c===b))});$('#take-photo').onclick=()=>takePhoto(async data=>{try{photoPending={key:id(),data};$('#photo-area').innerHTML=`<img class="photo-preview" alt="Private product photo" src="${data}"><button type="button" class="plain-link" id="clear-photo">Remove photo</button>`;$('#clear-photo').onclick=()=>{photoPending=null;$('#photo-area').innerHTML=''}}catch(e){toast('Photo could not be added')}});
$('#remove-form').onsubmit=async e=>{e.preventDefault();const action=e.submitter?.dataset.action||'remove';if(action==='nothing'&&state.active.some(a=>a.id!==sessionId)){toast('Log your other product out first, or save this removal.');return}const buttons=[...body.querySelectorAll('button[type=submit]')],leaked=$('#leaked').checked;savingRemoval=true;buttons.forEach(b=>b.disabled=true);let photoKey=null;try{const ml=P[x.type].ml&&$('#collected').value!==''?Number($('#collected').value):null;if(ml!==null&&(!Number.isFinite(ml)||ml<0||ml>500))throw Error('Enter a valid amount');if(photoPending){photoKey=photoPending.key;await photoPut(photoKey,photoPending.data)}transaction(()=>{M.finish(state,sessionId,{ml,soak,leaked,photo:photoKey,reinserted:action==='reinsert'},action==='reinsert');if(action==='replace')M.add(state,x.type,state.settings.hours[x.type]||P[x.type].hours);if(action==='nothing'){const d=M.day();state.days[d]={...state.days[d],nothingTonight:true}}});photoPending=null;savingRemoval=false;closeSheet();render();if(action==='nothing')nightMessage();else if(action==='remove'&&!state.active.length&&isNight())afterDark();else if(action==='reinsert'||action==='replace')insertedConfirmation(x.type);else toast(action==='reinsert'?'Emptied. Back in. Timer reset.':action==='replace'?'Fresh one. Fresh timer.':'Logged. '+(state.settings.cheeky?'Excellent extraction.':'All done.'))}catch(e){savingRemoval=false;if(photoKey)await photoDelete(photoKey).catch(()=>{});$('#form-error').innerHTML=`<p class="error">${safe(e.message)}</p>`;buttons.forEach(b=>b.disabled=false)}}}
function isNight(){const h=new Date().getHours();return h>=20||h<6}
function afterDark(){show(head('And for tonight?')+`<div class="empty">${art('cup',0,true)}<p class="caption">Anything going in or on before bed?</p></div><button class="btn full spaced" data-choose>Pick some protection</button><button class="btn outline full spaced" data-nothing>☾ Nothing tonight</button>`)}
function nothingTonight(){if(state.active.length){toast('Log your current products out first.');return}transaction(()=>{const d=M.day();state.days[d]={...state.days[d],nothingTonight:true}});closeSheet();render();nightMessage()}
function nightMessage(){show(head(state.settings.cheeky?'Ooo. Risky business.':'Off duty tonight.')+`<section class="card night-card">${DripArt.scene('everyday',3)}<h2>${state.settings.cheeky?'No backup. Brave.':'Nothing overnight'}</h2><p class="caption">${state.settings.cheeky?'The sheets wish you luck.':'Logged. No product timers are running.'}</p><button class="btn highlight full" data-close>${state.settings.cheeky?'I accept my fate':'Goodnight'}</button></section>`)}
function openSettings(){const s=setupStatus();show(head('Your rules.')+`<div class="product-intro">${art('cup')}<div><h3>Still In? <span class="caption">v0.3</span></h3><span class="caption">What's in. When it's out.</span></div></div><label class="switch-row"><span><strong>A little cheek?</strong><br><span class="caption">Playful comments. Serious reminders.</span></span><input type="checkbox" id="cheeky" ${state.settings.cheeky?'checked':''}></label><h3>Default reminders</h3><div class="settings-list">${Object.keys(P).map(k=>`<div class="row"><label for="hours-${k}">${P[k].name}</label><select id="hours-${k}" data-default="${k}">${[2,4,6,8,10,12].filter(h=>h<=P[k].max).map(h=>`<option value="${h}" ${(state.settings.hours[k]||P[k].hours)===h?'selected':''}>${h} hours</option>`).join('')}</select></div>`).join('')}</div><p class="note">These are reminder times, not guarantees of safe wear. Follow your product’s instructions. Changing a default won’t alter a running timer.</p>${native?`<h3 class="spaced">Phone reminders</h3><div class="setup-row row"><div>Notifications<br><span class="caption">${s.notifications?'Allowed ✓':'Not allowed'}</span></div><button class="btn secondary" data-permission="notifications">${s.notifications?'Settings':'Allow'}</button></div><div class="setup-row row"><div>Precise alarms<br><span class="caption">${s.exact?'Allowed ✓':'May be delayed'}</span></div><button class="btn secondary" data-permission="alarms">${s.exact?'Settings':'Allow'}</button></div><button class="btn outline full spaced" id="test-alarm">Test reminder in 10 seconds</button><p class="note">Check your alarm-channel sound in Android settings. Silent mode, Do Not Disturb, force-stopping the app, or a powered-off phone can affect alerts. Android may allow you to swipe away the countdown; the removal alarm remains scheduled.</p>`:`<div class="native-warning spaced"><strong>Phone alarms need the Android app.</strong><br>This web draft won’t remind you when it’s closed.<br><a class="btn secondary" href="still-in-0.3.apk" download>↓ Get the Android app</a></div>`}<h3 class="spaced">Your private stuff</h3><p class="caption">No login. No ads. No analytics. Your logs and photos stay on this device. Clearing app data or uninstalling removes them. Browser and APK logs are separate.</p><button class="btn outline full" id="export">Export logs + photos</button><p class="note">Only an export you request saves a copy outside the app. Keep that file private.</p><details><summary class="caption">Wear-time guidance</summary><p class="note">Tampons: change every 4–8 hours. Never more than 8 hours. Cup and disc instructions vary; check your brand’s stated limit. Overdue means past your chosen reminder, not a safe extension.</p><a class="plain-link" href="https://www.fda.gov/consumers/consumer-updates/facts-tampons-and-tampon-safety" target="_blank" rel="noopener">FDA tampon guidance</a></details>`);$('#cheeky').onchange=e=>doAction(()=>{transaction(()=>state.settings.cheeky=e.target.checked);render()});body.querySelectorAll('[data-default]').forEach(b=>b.onchange=()=>doAction(()=>transaction(()=>state.settings.hours[b.dataset.default]=Number(b.value))));$('#export').onclick=exportData;if(native)$('#test-alarm').onclick=()=>{StillAndroid.testAlarm();toast('Test set. Lock your phone and wait 10 seconds.')}}
function openSetup(){openSettings();body.querySelector('[data-permission]')?.scrollIntoView({behavior:'smooth',block:'center'})}
function bind(){document.querySelectorAll('nav [data-page]').forEach(b=>b.onclick=()=>{page=b.dataset.page;render();window.scrollTo(0,0)});$('#settings').onclick=openSettings;$('.brand').onclick=e=>{e.preventDefault();page='now';render()};document.querySelector('header [data-report]').onclick=()=>openReport();bindCommon(main);main.querySelectorAll('[data-date]').forEach(b=>b.onclick=()=>{selectedDay=b.dataset.date;render()});main.querySelectorAll('[data-month]').forEach(b=>b.onclick=()=>{month=new Date(month.getFullYear(),month.getMonth()+Number(b.dataset.month),1);timelineDays=7;render()});main.querySelectorAll('[data-calendar-view]').forEach(b=>b.onclick=()=>doAction(()=>{transaction(()=>state.settings.calendarView=b.dataset.calendarView);render()}));$('[data-earlier]')?.addEventListener('click',()=>{timelineDays+=7;render()});$('[data-clear-flow]')?.addEventListener('click',()=>doAction(()=>{transaction(()=>delete state.days[selectedDay].flow);render()}));$('[data-save-note]')?.addEventListener('click',()=>doAction(()=>{const note=$('#day-note').value;transaction(()=>state.days[selectedDay]={...state.days[selectedDay],note});toast('Note saved')}));}
function bindCommon(root){root.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>openAdd(b.dataset.add));root.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>openRemove(b.dataset.remove));root.querySelectorAll('[data-choose]').forEach(b=>b.onclick=choose);root.querySelectorAll('[data-nothing]').forEach(b=>b.onclick=()=>doAction(nothingTonight));root.querySelectorAll('[data-flow][data-day]').forEach(b=>b.onclick=()=>doAction(()=>{transaction(()=>{const note=$('#day-note'),d=b.dataset.day;state.days[d]={...state.days[d],flow:b.dataset.flow,...(note?{note:note.value}:{})};if(d===M.day())M.report(state,'flow',{flow:b.dataset.flow})});render();toast('Flow logged')}));root.querySelectorAll('[data-calendar]').forEach(b=>b.onclick=()=>{page='calendar';render()});root.querySelectorAll('[data-setup]').forEach(b=>b.onclick=openSetup);root.querySelectorAll('[data-view-photo]').forEach(b=>b.onclick=()=>viewPhoto(b.dataset.viewPhoto));root.querySelectorAll('[data-log]').forEach(b=>b.onclick=()=>logDetail(b.dataset.log));root.querySelectorAll('[data-report]').forEach(b=>b.onclick=()=>openReport());root.querySelectorAll('[data-event]').forEach(b=>b.onclick=()=>eventDetail(b.dataset.event));root.querySelectorAll('[data-day-detail]').forEach(b=>b.onclick=()=>{selectedDay=b.dataset.dayDetail;transaction(()=>state.settings.calendarView='month');page='calendar';render()});}
function bindSheet(){bindCommon(body);body.querySelectorAll('[data-close]').forEach(b=>b.onclick=closeSheet);body.querySelectorAll('[data-hours]').forEach(b=>b.onclick=()=>{body.querySelectorAll('[data-hours]').forEach(c=>c.classList.toggle('selected',c===b));$('#wear-hours').value=b.dataset.hours});body.querySelectorAll('[data-permission]').forEach(b=>b.onclick=()=>StillAndroid.permission(b.dataset.permission))}
function logDetail(logId){const x=state.history.find(a=>a.id===logId);if(!x)return;show(head(P[x.type].name+' receipt')+`<div class="product-intro">${art(x.type,x.soak??0)}<div><h3>${durationText(x.end-x.start)}</h3><span class="caption">${dateLabel(M.day(x.end))}</span></div></div><p class="caption">${new Date(x.start).toLocaleString()}<br>to ${new Date(x.end).toLocaleString()}</p><p>${x.ml!=null?`${x.ml} ml collected`:x.soak!=null?['Dry','A little soaked','Half soaked','Mostly soaked','Fully soaked'][x.soak]:'No amount logged'}${x.leaked?' · Leaked':''}</p>${x.photo?`<button class="btn secondary full" data-view-photo="${safe(x.photo)}">View private photo</button>`:''}<p class="note">${x.end>x.due?'Removed '+durationText(x.end-x.due)+' after your reminder time.':'Removed before your reminder time.'}</p><button class="btn danger full" id="delete-log">Delete this receipt</button><div id="delete-confirm"></div>`);$('#delete-log').onclick=()=>{$('#delete-confirm').innerHTML='<p class="caption">Delete this log and its photo? This cannot be undone.</p><button class="btn danger full" id="really-delete">Yes, delete</button>';$('#really-delete').onclick=()=>doAction(()=>{transaction(()=>state.history=state.history.filter(a=>a.id!==logId));if(x.photo)photoDelete(x.photo).catch(()=>{});closeSheet();render();toast('Receipt deleted')})}}
function photoDb(){return new Promise((resolve,reject)=>{const q=indexedDB.open('still-in-private-photos',1);q.onupgradeneeded=()=>q.result.createObjectStore('photos');q.onsuccess=()=>resolve(q.result);q.onerror=()=>reject(Error('Photo storage unavailable'))})}
async function photoOp(mode,fn){const db=await photoDb();return new Promise((resolve,reject)=>{const t=db.transaction('photos',mode);let result;const q=fn(t.objectStore('photos'));q.onsuccess=()=>result=q.result;t.oncomplete=()=>{db.close();resolve(result)};t.onerror=()=>{db.close();reject(Error('Could not save photo'))}})}
const photoPut=(k,d)=>photoOp('readwrite',s=>s.put(d,k)),photoGet=k=>photoOp('readonly',s=>s.get(k)),photoDelete=k=>photoOp('readwrite',s=>s.delete(k));
async function viewPhoto(key){try{const data=await photoGet(key);if(!data)throw Error('Photo no longer available');show(head('For your eyes only.')+`<img class="photo-preview" style="max-height:65vh" src="${data}" alt="Private product photo"><p class="note">Only stored inside this app.</p>`)}catch(e){toast(e.message)}}
function takePhoto(cb){photoCallback=cb;if(native){StillAndroid.takePhoto();return}browserCamera(cb)}
window.onNativePhoto=data=>{if(data&&photoCallback){const cb=photoCallback;photoCallback=null;cb(data)}else if(!data)toast('Photo cancelled')};
async function browserCamera(cb){try{stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'},width:{ideal:1280}},audio:false});const overlay=document.createElement('div');overlay.id='camera-overlay';overlay.style.cssText='position:fixed;inset:0;background:#100d10;z-index:50;display:flex;flex-direction:column;padding:25px;gap:20px;color:white';overlay.innerHTML='<div class="row"><strong>Private camera</strong><button class="btn secondary" id="camera-cancel">Cancel</button></div><video id="camera-video" autoplay playsinline style="width:100%;min-height:0;flex:1;object-fit:contain"></video><button class="btn highlight" id="camera-capture">Take photo</button>';document.body.append(overlay);const video=$('#camera-video');video.srcObject=stream;const stop=()=>{stream?.getTracks().forEach(t=>t.stop());stream=null;overlay.remove()};$('#camera-cancel').onclick=stop;$('#camera-capture').onclick=()=>{if(!video.videoWidth)return;const c=document.createElement('canvas'),scale=Math.min(1,1000/video.videoWidth);c.width=video.videoWidth*scale;c.height=video.videoHeight*scale;c.getContext('2d').drawImage(video,0,0,c.width,c.height);const data=c.toDataURL('image/jpeg',.8);stop();cb(data)}}catch(e){toast('Camera unavailable or permission denied. No photo saved.')}}
async function exportData(){try{toast('Preparing your private export…');const photos={};for(const x of state.history){if(x.photo)photos[x.photo]=await photoGet(x.photo)}const data=JSON.stringify({app:'Still In?',exportedAt:new Date().toISOString(),state,photos},null,2);if(native){StillAndroid.exportData(data);return}const url=URL.createObjectURL(new Blob([data],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='still-in-private-export-'+M.day()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e){toast('Could not export: '+e.message)}}
function art(type,soak=0,sleep=false){if(type==='pants')return legacyArt(type,soak,sleep);return DripArt.product(type,Math.round(Math.max(0,Math.min(4,soak))*5/4))}
function stageArt(x){const f=M.dripFrame(x);return DripArt.scene(f.sheet,f.index,'drip-art',f.idle?'Drip relaxing while time passes':'Drip illustrating elapsed wear time')}
function endTime(ts){return (M.day(ts)!==M.day()?new Date(ts).toLocaleDateString([],{weekday:'short'})+' ':'')+time(ts)}
function wearTimeline(x,compact=false){return `<div class="wear-timeline ${compact?'compact':''}"><div class="wear-ends"><div><span>${P[x.type].internal?'Put in':'Put on'}</span><strong>${endTime(x.start)}</strong></div><div><span>${P[x.type].internal?'Take out by':'Change by'}</span><strong>${endTime(x.due)}</strong></div></div><div class="wear-track" role="progressbar" aria-label="Elapsed wear time" aria-valuemin="0" aria-valuemax="100" aria-valuenow="0"><span class="wear-fill"></span><span class="wear-now"><i></i><small>Now</small></span></div><p class="wear-status caption" data-timer-label></p></div>`}
function calendarTop(mode){return `<div class="eyebrow">The full story</div><div class="row calendar-title"><h1>Your calendar.</h1><div class="view-switch" aria-label="Calendar view"><button data-calendar-view="timeline" class="${mode==='timeline'?'selected':''}">Timeline</button><button data-calendar-view="month" class="${mode==='month'?'selected':''}">Month</button></div></div>`}
function monthNavigation(){return `<div class="calendar-head"><button class="icon-button" data-month="-1" aria-label="Previous month">‹</button><h2>${month.toLocaleDateString([],{month:'long',year:'numeric'})}</h2><button class="icon-button" data-month="1" aria-label="Next month">›</button></div>`}
function dayStatus(key){const events=(state.events||[]).filter(x=>M.day(x.at)===key&&['flow','heavy','bleeding','clear','wake_dry'].includes(x.type)).reverse().sort((a,b)=>b.at-a.at),e=events[0];if(e){if(e.type==='flow')return {flow:e.flow,label:(e.flow==='none'?'No blood logged':e.flow[0].toUpperCase()+e.flow.slice(1)+' flow')+' · '+time(e.at)};return {flow:e.type==='heavy'?'heavy':e.type==='bleeding'?'medium':'none',label:(e.type==='heavy'?'Heavy bleeding':e.type==='bleeding'?'Bleeding started':'No blood reported')+' · '+time(e.at)}}const flow=state.days[key]?.flow;return flow?{flow,label:flow==='none'?'No blood logged':flow[0].toUpperCase()+flow.slice(1)+' flow'}:{flow:'unlogged',label:'Flow not logged'}}

function renderCalendarTimeline(){
 const y=month.getFullYear(),m=month.getMonth(),daysInMonth=new Date(y,m+1,0).getDate(),today=new Date(),isCurrent=y===today.getFullYear()&&m===today.getMonth(),end=isCurrent?today.getDate():daysInMonth,start=Math.max(1,end-timelineDays+1),future=new Date(y,m,1)>today;
 main.innerHTML=calendarTop('timeline')+`<section class="timeline-intro">${monthNavigation()}<p class="caption">Follow the days. Every change, every plot twist.</p><div class="timeline-key"><span><i class="key-wear"></i> Product wear</span><span><i class="key-report"></i> Report</span></div></section>${future?'<p class="caption">Nothing to log here yet.</p>':`${start>1?'<button class="plain-link earlier-days" data-earlier>＋ Earlier days in this month</button>':''}<div class="calendar-story">${storyDays(y,m,start,end).map(item=>{if(item.gap)return `<div class="story-gap"><span>${item.start}–${item.end}</span><p>${month.toLocaleDateString([],{month:'short'})} · No entries logged</p></div>`;const d=new Date(y,m,item.day),key=M.day(d),status=dayStatus(key),events=M.entriesForDay(state,key),sessions=M.sessionsForDay(state,key),note=state.days[key]?.note;return `<section class="story-day ${key===M.day()?'story-today':''}" data-flow="${status.flow}"><div class="story-date"><span>${d.toLocaleDateString([],{weekday:'short'})}</span><button data-day-detail="${key}" aria-label="Open ${dateLabel(key)}">${d.getDate()}</button></div><div class="story-day-body"><div class="row"><h3>${key===M.day()?'Today':d.toLocaleDateString([],{month:'short',day:'numeric'})}</h3><span class="story-flow">${status.label}</span></div>${wearLanes(key,sessions)}${events.length?`<div class="story-events">${events.map(storyEntry).join('')}</div>`:`<p class="unlogged">${state.days[key]?.nothingTonight?'☾ No protection overnight':'No events logged'}</p>`}${note?`<p class="day-note">${safe(note)}</p>`:''}</div></section>`}).join('')}</div>`}<div class="footer-note">The line shows your logs, not a prediction.<br>Drip’s scenes show wear time, not blood loss.</div>`;
}
function storyDays(y,m,start,end){const out=[];for(let day=start;day<=end;day++){const key=M.day(new Date(y,m,day)),d=state.days[key],has=key===M.day()||d?.flow||d?.note||d?.nothingTonight||M.entriesForDay(state,key).length||M.sessionsForDay(state,key).length;if(has){out.push({day});continue}const last=out[out.length-1];if(last?.gap)last.end=day;else out.push({gap:true,start:day,end:day})}return out}
function wearLanes(key,sessions){if(!sessions.length)return '';return `<div class="day-wear"><div class="hour-labels"><span>00</span><span>06</span><span>12</span><span>18</span><span>24</span></div>${sessions.map(x=>`<div class="wear-lane"><span class="lane-icon">${art(x.type)}</span><div class="lane-track"><button class="lane-span ${x.type}" style="left:${x.left*100}%;width:${Math.min(100-x.left*100,Math.max(1,x.width*100))}%" ${x.active?`data-remove="${x.id}"`:`data-log="${x.id}"`} aria-label="${P[x.type].name}, ${endTime(x.start)} to ${x.active?'now':endTime(x.end)}"></button></div></div>`).join('')}</div>`}
function reportLabel(e){if(e.type==='flow')return e.flow==='none'?'No blood logged':e.flow[0].toUpperCase()+e.flow.slice(1)+' flow';return M.reportTypes[e.type]+(e.type==='cramps'?' · '+crampLabels[e.severity-1]:'')}
function reportIcon(e,css='report-art'){return e.type==='flow'?`<span class="${css} flow-report-icon">${drop(e.flow)}</span>`:DripArt.report(e.type,e.severity||1,css)}
function storyEntry(entry){if(entry.kind==='report'){const e=entry.event;return `<button class="story-event report-event" data-event="${e.id}"><time>${time(e.at)}</time>${reportIcon(e)}<span><strong>${safe(reportLabel(e))}</strong>${e.note?`<small>${safe(e.note)}</small>`:''}</span></button>`}const x=entry.session,isOut=entry.kind==='out',detail=isOut?(x.ml!=null?`${x.ml} ml collected`:x.soak!=null?['Dry','A little soaked','Half soaked','Mostly soaked','Fully soaked'][x.soak]:''):'',button=isOut?`data-log="${x.id}"`:(state.active.some(a=>a.id===x.id)?`data-remove="${x.id}"`:`data-log="${x.id}"`);return `<button class="story-event" ${button}><time>${time(entry.at)}</time>${art(x.type,isOut?(x.soak??0):0)}<span><strong>${P[x.type].name} ${isOut?(P[x.type].internal?'out':'changed'):(P[x.type].internal?'in':'on')}</strong>${detail?`<small>${detail}</small>`:''}${isOut&&x.leaked?'<small>Leaked</small>':''}</span></button>`}
function dayEntries(key){const entries=M.entriesForDay(state,key);return entries.length?`<section class="story-events standalone-events">${entries.map(storyEntry).join('')}</section>`:'<p class="caption">No events logged for this day.</p>'}
function openReport(note=''){show(head('What’s happening?')+`<p class="caption report-date">${new Date().toLocaleDateString([],{weekday:'short',day:'numeric',month:'short'})} · ${time(Date.now())}</p><div class="report-grid">${['cramps','leak','wake_dry','wake_blood','bleeding','heavy','clear','other'].map(type=>`<button class="report-choice" data-report-type="${type}">${DripArt.report(type,type==='cramps'?2:1)}<strong>${M.reportTypes[type]}</strong></button>`).join('')}</div><div class="field"><label for="report-note">A little detail? <span class="muted">Optional</span></label><textarea id="report-note" rows="2" maxlength="1000" placeholder="Anything to add…">${safe(note)}</textarea></div><p class="note">Tap an event to log it now. Reports are automatically timestamped.</p>`);body.querySelectorAll('[data-report-type]').forEach(b=>b.onclick=()=>{const type=b.dataset.reportType,note=$('#report-note').value;if(type==='cramps')openCramps(note);else if(type==='other')openNoteReport(note);else saveReport(type,null,note)})}
function openCramps(note=''){show(head('How bad are the cramps?')+`<div class="cramp-grid">${crampLabels.map((label,i)=>`<button class="cramp-choice" data-severity="${i+1}">${DripArt.report('cramps',i+1)}<strong>${i+1} · ${label}</strong></button>`).join('')}</div><div class="field"><label for="report-note">Optional note</label><textarea id="report-note" rows="2" maxlength="1000">${safe(note)}</textarea></div><p class="note">Tap a level to save it with the current time.</p>`);body.querySelectorAll('[data-severity]').forEach(b=>b.onclick=()=>saveReport('cramps',Number(b.dataset.severity),$('#report-note').value))}
function openNoteReport(note=''){show(head('Spill the details.')+`<form id="note-report"><div class="field"><label for="report-note">What happened?</label><textarea id="report-note" required maxlength="1000" rows="4">${safe(note)}</textarea></div><button class="btn full" type="submit">Save report</button></form>`);$('#note-report').onsubmit=e=>{e.preventDefault();if(!$('#report-note').value.trim()){toast('Add a note first');return}saveReport('other',null,$('#report-note').value)}}
function saveReport(type,severity,note){doAction(()=>{const e=transaction(()=>M.report(state,type,{severity,note}));closeSheet();render();toast('Logged · '+time(e.at))})}
function eventDetail(eventId){const e=state.events.find(x=>x.id===eventId);if(!e)return;show(head('The report.')+`<div class="event-hero">${reportIcon(e,'drip-art')}<h2>${safe(reportLabel(e))}</h2><p class="caption">${dateLabel(M.day(e.at))} · ${time(e.at)}</p>${e.note?`<p>${safe(e.note)}</p>`:''}</div><button class="btn danger full" id="delete-event">Delete report</button><div id="delete-event-confirm"></div>`);$('#delete-event').onclick=()=>{$('#delete-event-confirm').innerHTML='<p class="caption">Delete this report permanently?</p><button class="btn danger full" id="confirm-delete-event">Yes, delete report</button>';$('#confirm-delete-event').onclick=()=>doAction(()=>{transaction(()=>state.events=state.events.filter(x=>x.id!==eventId));closeSheet();render();toast('Report deleted')})}}
function insertedConfirmation(type){const x=state.active.find(a=>a.type===type);if(!x)return;const late=M.timer(x).overdue;show(head(late?'Already due.':(P[type].internal?'It’s in.':'It’s on.'))+`<div class="inserted-confirm">${late?stageArt(x):DripArt.scene('everyday',{tampon:12,cup:13,disc:14,pad:15,liner:15,pants:15}[type]||12)}<h2>${late?'Time for a change.':(state.settings.cheeky?'Drip’s on the clock.':'Reminder started.')}</h2><p class="caption">${late?'Logged with your original start time.':P[type].name+' · '+(P[type].internal?'take out':'change')+' by '+endTime(x.due)}</p><button class="btn velvet-button full" data-close>${late?'Got it':'All set'}</button></div>`)}
window.onNativeResume=()=>{if(native){try{state=M.validate(JSON.parse(StillAndroid.getState()));if(!sheet.open)render();else if($('#test-alarm'))openSettings()}catch(e){toast('Could not refresh saved state')}}};
sheet.addEventListener('cancel',e=>{if(savingRemoval){e.preventDefault();return}if(stream){stream.getTracks().forEach(t=>t.stop());stream=null}photoCallback=null});sheet.addEventListener('click',e=>{if(e.target===sheet){const r=sheet.getBoundingClientRect();if(e.clientY<r.top||e.clientX<r.left||e.clientX>r.right)closeSheet()}});document.addEventListener('visibilitychange',()=>{if(!document.hidden&&!sheet.open){if(M.day()!==selectedDay&&page==='now')selectedDay=M.day();render()}});render();
